    <script>
        let assetList = [];
        let viewedAssetIndex = 0;

        // Helper to safely get value from [value, "description"] format
        const getValue = (prop) => (Array.isArray(prop) ? prop[0] : prop) ?? "---";

        // Update a progress bar
        const updateProgressBar = (elementId, value) => {
            const bar = document.getElementById(elementId);
            if (bar) {
                const numericValue = parseInt(value, 10) || 0;
                bar.style.width = `${numericValue}%`;
                bar.innerText = `${numericValue}%`;
            }
        };

        // Update Corporate & Report Info
        function updateGlobalInfo(data) {
            // Report Header
            document.getElementById('report-timestamp').innerText = getValue(data.report_header?.timestamp);
            document.getElementById('report-location').innerText = getValue(data.report_header?.location_alias);
            // Corporate Assets
            document.getElementById('corp-capital').innerText = `${getValue(data.corporate_assets?.liquid_capital)} 百万元`;
            document.getElementById('corp-reserve').innerText = `${getValue(data.corporate_assets?.temporal_reserve_years)} 年`;
        }

        // Update On-Site Personnel
        function updatePersonnelInfo(data) {
            const personnelSection = document.getElementById('personnel-section');
            // Clear previous entries but keep the title
            while (personnelSection.children.length > 1) {
                personnelSection.removeChild(personnelSection.lastChild);
            }

            const personnel = data.personnel_on_site;
            if (!personnel || Object.keys(personnel).length === 0) {
                 personnelSection.insertAdjacentHTML('beforeend', `<div class="value" style="text-align:center;">无现场人员</div>`);
                 return;
            }

            for (const name in personnel) {
                // Skip $meta property
                if (name === '$meta') continue;

                const p = personnel[name];
                const personnelHTML = `
                    <div class="personnel-block">
                        <div class="row"><span class="label">${name}:</span><span class="value">${getValue(p.emotional_state)}</span></div>
                        <div class="row"><span class="label">任务:</span><span class="value">${getValue(p.status_note)}</span></div>
                        <div class="row"><span class="label">位置:</span><span class="value">${getValue(p.location)}</span></div>
                    </div>
                `;
                personnelSection.insertAdjacentHTML('beforeend', personnelHTML);
            }
        }


        // Render the currently selected asset
        function renderAsset(index) {
            try {
                if (!assetList || assetList.length === 0) {
                    document.getElementById('asset-identifier').innerText = "无资产记录";
                    document.getElementById('unprocessed-asset-panel').classList.add('hidden');
                    document.getElementById('processed-asset-panel').classList.add('hidden');
                    return;
                }
                if (index < 0 || index >= assetList.length) return;

                const asset = assetList[index];
                const unprocessedPanel = document.getElementById('unprocessed-asset-panel');
                const processedPanel = document.getElementById('processed-asset-panel');
                const statusIndicator = document.getElementById('asset-status-indicator');

                if (asset._status_type === 'unprocessed') {
                    unprocessedPanel.classList.remove('hidden');
                    processedPanel.classList.add('hidden');
                    statusIndicator.className = 'asset-status-tag unprocessed';
                    statusIndicator.innerText = '待处理';

                    document.getElementById('asset-identifier').innerText = getValue(asset.asset_tag);
                    document.getElementById('unprocessed-name').innerText = getValue(asset.former_identity?.name);

                    updateProgressBar('unprocessed-conversion', getValue(asset.psychological_profile?.conversion_progress));
                    updateProgressBar('unprocessed-stress', getValue(asset.somatic_profile?.stress_level_percent));
                    updateProgressBar('unprocessed-resilience', getValue(asset.psychological_profile?.mental_resilience));

                    document.getElementById('unprocessed-emotion').innerText = getValue(asset.psychological_profile?.dominant_emotion);
                    document.getElementById('unprocessed-awareness').innerText = getValue(asset.psychological_profile?.situational_awareness);
                    document.getElementById('unprocessed-pstate').innerText = getValue(asset.somatic_profile?.physical_state);
                    document.getElementById('unprocessed-attire').innerText = getValue(asset.somatic_profile?.attire_condition);

                } else if (asset._status_type === 'processed') {
                    unprocessedPanel.classList.add('hidden');
                    processedPanel.classList.remove('hidden');
                    statusIndicator.className = 'asset-status-tag processed';
                    statusIndicator.innerText = '已转化';

                    document.getElementById('asset-identifier').innerText = getValue(asset.former_name);
                    document.getElementById('processed-id').innerText = getValue(asset.collection_number);

                    updateProgressBar('processed-loyalty', getValue(asset.psychological_profile?.loyalty));
                    updateProgressBar('processed-obedience', getValue(asset.psychological_profile?.obedience));
                    updateProgressBar('processed-initiative', getValue(asset.psychological_profile?.initiative));
                    updateProgressBar('processed-arousal', getValue(asset.somatic_profile?.arousal_level_percent));

                    document.getElementById('processed-tier').innerText = getValue(asset.tier);
                    document.getElementById('processed-value').innerText = getValue(asset.current_value);
                    document.getElementById('processed-lens').innerText = getValue(asset.psychological_profile?.dominant_lens);
                    document.getElementById('processed-mental').innerText = getValue(asset.psychological_profile?.mental_state);
                }
            } catch (error) {
                console.error("Render Asset Error:", error);
                document.getElementById('asset-identifier').innerText = "渲染错误";
            }
        }

        // Initialize the entire display
        async function initDisplay() {
            try {
                const msgID = getCurrentMessageId();
                const messages = await getChatMessages(msgID);
                if (!messages || messages.length === 0) return;

                let data = null;
                for (let i = messages.length - 1; i >= 0; i--) {
                    const msg = messages[i];
                    if (msg && msg.data && msg.data.stat_data) {
                        data = msg.data.stat_data;
                        break;
                    }
                }

                if (!data) {
                    console.error("MVU Error: No valid stat_data found.");
                    return;
                }

                // Update static sections
                updateGlobalInfo(data);
                updatePersonnelInfo(data);

                // Build the combined asset list
                assetList = [];
                if (data.unprocessed_assets) {
                    for (const key in data.unprocessed_assets) {
                        if (key === '$meta') continue;
                        assetList.push({ ...data.unprocessed_assets[key], _status_type: 'unprocessed' });
                    }
                }
                if (data.processed_assets) {
                    for (const key in data.processed_assets) {
                         if (key === '$meta') continue;
                        assetList.push({ ...data.processed_assets[key], _status_type: 'processed' });
                    }
                }

                viewedAssetIndex = 0;
                renderAsset(viewedAssetIndex);

            } catch (error) {
                console.error("Status Bar Init Error:", error);
            }
        }

        document.getElementById('next-asset').addEventListener('click', () => {
            if (assetList.length === 0) return;
            viewedAssetIndex = (viewedAssetIndex + 1) % assetList.length;
            renderAsset(viewedAssetIndex);
        });

        document.getElementById('prev-asset').addEventListener('click', () => {
            if (assetList.length === 0) return;
            viewedAssetIndex = (viewedAssetIndex - 1 + assetList.length) % assetList.length;
            renderAsset(viewedAssetIndex);
        });

        document.addEventListener("DOMContentLoaded", initDisplay);
    </script>
</body>
</html>
